INSERT INTO `books` VALUES (1,'Cho tôi xin một vé đi tuổi thơ','Câu chuyện về tuổi thơ và những kỷ niệm.','https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSpSL1wAHh7u2sRE-AXnOeD48FZ2uq5BiaYNkOS2Npl3w&s=10',2,1,1,85000.00,30,'active','2026-10-19 09:46:34','2026-10-21 07:40:35'),(2,'Mắt biếc','Câu chuyện tình cảm và ký ức tuổi trẻ.','https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTpmUU7f5jz6CF-xycuNfj-eD07liXLA3yOLkiiGVQIUQ&s=10',2,1,1,95000.00,25,'active','2026-10-19 09:46:34','2026-10-21 07:40:36'),(3,'Tôi thấy hoa vàng trên cỏ xanh','Câu chuyện về tuổi thơ ở làng quê.','https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTn1L3-abEFoSpgEIZ1zvHAeUTewkyBZtgZ4WYHKKNvaR325ASVhuazrqvJ&s=10',2,1,1,110000.00,20,'active','2026-10-19 09:46:34','2026-10-21 07:40:36'),(4,'Kính vạn hoa','Những câu chuyện học đường vui nhộn.','https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTIBiKD8-mXshus7KrcRH52nzR7b-dVDeV0-Qr1OfRcqQ&s=10',1,1,0,75000.00,40,'active','2026-10-19 09:46:34','2026-10-21 07:40:37'),(5,'Dế Mèn phiêu lưu ký','Hành trình phiêu lưu của Dế Mèn.','https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTLqO3c5DHRRhJYWi6bnyjXwdR4FS0w-frHTr0dnzWtGA&s=10',1,1,1,60000.00,35,'active','2026-10-19 09:46:34','2026-10-21 07:40:38'),(6,'Chí Phèo','Tác phẩm văn học hiện thực Việt Nam.','https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQq2rboGYmUHuxTF9gpl1rnPVStn8GpkIJoaVf-FxWLVw&s=10',3,0,1,0.00,0,'active','2026-10-19 09:46:34','2026-10-21 07:40:39'),(7,'Lão Hạc','Truyện ngắn về cuộc sống người nông dân.','https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQznaWPgNBREI95IWNGdQ-GSjptLseIcwyBfGZz5qHoFw&s=10',3,0,1,0.00,0,'active','2026-10-19 09:46:34','2026-10-21 07:40:39'),(8,'Tắt đèn','Tiểu thuyết phản ánh xã hội Việt Nam xưa.','https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTXonKafl3YzqW0GzNDfbPCBmwonsqeFRIO_6pzYWhWOA&s=10',3,1,1,65000.00,15,'active','2026-10-19 09:46:34','2026-10-21 07:40:40'),(9,'Hai đứa trẻ','Truyện ngắn về cuộc sống nơi phố huy